package lk.repairdesk.api.security; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.util.*; import java.util.function.Function; @Service public class JwtService { private final SecretKey key; private final long expiration; public JwtService(@Value("${app.jwt.secret}") String secret,@Value("${app.jwt.expiration-ms}") long expiration){this.key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.expiration=expiration;} public String generate(UserDetails u){var now=new Date();return Jwts.builder().subject(u.getUsername()).issuedAt(now).expiration(new Date(now.getTime()+expiration)).signWith(key).compact();} public String username(String token){return claim(token,Claims::getSubject);} public boolean valid(String token,UserDetails u){return username(token).equalsIgnoreCase(u.getUsername())&&!claim(token,Claims::getExpiration).before(new Date());} private <T>T claim(String t,Function<Claims,T> f){return f.apply(Jwts.parser().verifyWith(key).build().parseSignedClaims(t).getPayload());} }